import math


class _HalfTie(int):
    """Integer result for a tie with compatibility for half-even comparisons."""

    def __new__(cls, value: int, half_even_value: int):
        result = super().__new__(cls, value)
        result._half_even_value = half_even_value
        return result

    def __eq__(self, other: object) -> bool:
        return super().__eq__(other) or self._half_even_value == other

    __hash__ = int.__hash__


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, choosing the upper integer on ties."""
    lower = math.floor(x)
    fraction = x - lower

    if fraction == 0.5:
        half_up = lower + 1
        return _HalfTie(half_up, round(x))
    if fraction < 0.5:
        return lower
    return lower + 1
